// Find the earliest Friday the 13th and count them in a 400-year cycle
// using the proleptic Gregorian calendar.

// Earliest Friday the 13th starting from 0001-01-01
DateOnly date = new(1, 1, 13); // start checking the 13th of each month
DateOnly earliest = default;

while (date.Year < 10000)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
date = new DateOnly(1, 1, 13);

while (date.Year <= 400)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
        count++;
    date = date.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle (years 1-400): {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month
var byMonth = new int[12];
date = new DateOnly(1, 1, 13);

while (date.Year <= 400)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
        byMonth[date.Month - 1]++;
    date = date.AddMonths(1);
}

Console.WriteLine("\nDistribution by month (400-year cycle):");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

